import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CoreFunction_functionRound_TriageGen0Test {

    private CoreFunction coreFunction;
    private Expression mockArg1;
    private EvalContext mockContext;

    @Before
    public void setUp() {
        // functionCode is arbitrary for this test
        // args contains one expression for functionRound
        mockArg1 = mock(Expression.class);
        Expression[] args = new Expression[]{mockArg1};
        coreFunction = new CoreFunction(1, args);
        mockContext = mock(EvalContext.class);
    }

    /**
     * Tests rounding up for a positive decimal.
     */
    @Test
    public void testFunctionRound_PositiveRoundingUp() throws Throwable {
        when(mockArg1.computeValue(mockContext)).thenReturn(2.5);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(3.0, (Double) result, 0.0);
    }

    /**
     * Tests rounding down for a positive decimal.
     */
    @Test
    public void testFunctionRound_PositiveRoundingDown() throws Throwable {
        when(mockArg1.computeValue(mockContext)).thenReturn(2.4);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(2.0, (Double) result, 0.0);
    }

    /**
     * Tests rounding for a negative decimal (Math.round behavior).
     * Math.round(-2.5) is -2.
     */
    @Test
    public void testFunctionRound_NegativeRounding() throws Throwable {
        when(mockArg1.computeValue(mockContext)).thenReturn(-2.5);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(-2.0, (Double) result, 0.0);
    }

    /**
     * Tests rounding for a negative decimal (Math.round behavior).
     * Math.round(-2.51) is -3.
     */
    @Test
    public void testFunctionRound_NegativeRoundingDown() throws Throwable {
        when(mockArg1.computeValue(mockContext)).thenReturn(-2.51);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(-3.0, (Double) result, 0.0);
    }

    /**
     * Tests rounding for zero.
     */
    @Test
    public void testFunctionRound_Zero() throws Throwable {
        when(mockArg1.computeValue(mockContext)).thenReturn(0.0);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(0.0, (Double) result, 0.0);
    }

    /**
     * Tests that the method throws an exception if the argument count is not 1.
     * Since assertArgCount is protected and internal, this tests the logic branch.
     */
    @Test(expected = RuntimeException.class)
    public void testFunctionRound_WrongArgumentCount() throws Throwable {
        // Create a function with 0 arguments
        CoreFunction invalidFunction = new CoreFunction(1, new Expression[0]);
        invalidFunction.functionRound(mockContext);
    }

    /**
     * Helper method to access the protected method functionRound via reflection or subclass.
     * Since we are in the same package, we can use a subclass or direct access if possible.
     * Here we use a subclass to expose the protected method.
     */
    private Object invokeFunctionRound(EvalContext context) throws Throwable {
        return new TestableCoreFunction(1, new Expression[]{mockArg1}).functionRound(context);
    }

    /**
     * Subclass to allow testing of the protected method.
     */
    private static class TestableCoreFunction extends CoreFunction {
        public TestableCoreFunction(int functionCode, Expression[] args) {
            super(functionCode, args);
        }

        @Override
        protected Object functionRound(EvalContext context) {
            // We must call the actual implementation
            try {
                java.lang.reflect.Method method = CoreFunction.class.getDeclaredMethod("functionRound", EvalContext.class);
                method.setAccessible(true);
                return method.invoke(this, context);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        // Since we cannot easily override the call to super.functionRound if it's private, 
        // we use the reflection approach inside the test helper instead.
        // But for simplicity in this specific test structure, we'll assume the developer 
        // wants a standard visibility-bypass.
    }

    // Re-implementing the helper using reflection to ensure it hits the real logic
    private Object invokeFunctionRoundReflection(CoreFunction func, EvalContext context) throws Throwable {
        java.lang.reflect.Method method = CoreFunction.class.getDeclaredMethod("functionRound", EvalContext.class);
        method.setAccessible(true);
        return method.invoke(func, context);
    }
}
